import random
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq); comp=str.maketrans("ACGT","TGCA")

def orfs_coverage(s, minaa=100):
    intervals=[]
    for strand,sgn in ((s,1),(s.translate(comp)[::-1],-1)):
        for frame in range(3):
            start=None; j=frame
            while j+3<=len(s):
                cod=strand[j:j+3]
                if cod=='ATG' and start is None: start=j
                if cod in ('TAA','TAG','TGA') and start is not None:
                    if (j+3-start)//3-1>=minaa: intervals.append((start,j+3))
                    start=None
                j+=3
    return intervals

def cov(intervals,L):
    iv=sorted(intervals); tot=0; ce=-1
    for a,b in iv:
        if a>ce: tot+=b-a; ce=b
        elif b>ce: tot+=b-ce; ce=b
    return tot, len(intervals)

iv=orfs_coverage(seq)
tot,cnt=cov(iv,n)
print(f"real: {cnt} ORFs >=100aa, coverage {tot} bp ({100*tot/n:.0f}%)")

random.seed(3); pool=list(seq); totl=[];cntl=[]
for t in range(100):
