def longest_no_stop(s, stops):
    best=(0,0)
    cur=0; start=0
    for i in range(len(s)-2):
        if i%1==0:
            if s[i:i+3] in stops:
                cur=0; start=i+3
            else:
                cur+=1
                if cur>best[0]: best=(cur,start)
    return best

