def longest_frame(s, stops):
    out=[]
    for f in range(3):
        cur=0; start=f
        for j in range(f, len(s)-2, 3):
            if s[j:j+3] in stops:
                if cur>0: out.append((cur,start,j))
                cur=0; start=j+3
            else:
                cur+=1
        out.append((cur,start,len(s)))
    out.sort(reverse=True)
    return out[0]

